MATCH (c:Company {name: "Space Environment Technologies"})-[:hasCEO]->(p:Person)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasCEO]->(p)
  WHERE r.end_year IS NOT NULL
}
RETURN p.name

MATCH (c:Company)-[:foundedBy]->(p:Person)
WHERE EXISTS {
  MATCH (c)-[:hasBoardMember]->(:Person {name: "Roberto Setúbal"})
}
RETURN DISTINCT p.gender
